package info.deltaindices.volumecamera;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.core.content.ContextCompat;import androidx.documentfile.provider.DocumentFile;import com.google.common.util.concurrent.ListenableFuture;import java.io.*;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;
public final class CaptureActivity extends AppCompatActivity {
 static final String ACTION_TOGGLE="info.deltaindices.volumecamera.TOGGLE";private static volatile boolean active=false;private final Handler handler=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private ImageCapture capture;private TextView status;private final Runnable cycle=new Runnable(){public void run(){take();}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}else getWindow().addFlags(WindowManager.LayoutParams.FLAG_SHOW_WHEN_LOCKED|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(active){finish();return;}show();startCamera();}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);stopAndFinish();}
 private void show(){active=true;LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(40,40,40,40);status=new TextView(this);status.setTextSize(24);status.setText("Preparing rear camera…");box.addView(status);Button stop=new Button(this);stop.setText("STOP CAPTURE");stop.setOnClickListener(v->stopAndFinish());box.addView(stop);setContentView(box);Notifications.channel(this);getSystemService(NotificationManager.class).notify(Notifications.CAPTURE_ID,Notifications.build(this,"Taking pictures","Rear camera · flash off · every "+Settings.interval(this)+" seconds",true));}
 private void startCamera(){if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){status.setText("Camera permission is required");return;}ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(this);future.addListener(()->{try{ProcessCameraProvider provider=future.get();capture=new ImageCapture.Builder().setFlashMode(ImageCapture.FLASH_MODE_OFF).setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).build();provider.unbindAll();provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,capture);status.setText("Capturing every "+Settings.interval(this)+" seconds");handler.post(cycle);}catch(Exception e){status.setText("Camera unavailable: "+e.getMessage());}},ContextCompat.getMainExecutor(this));}
 private void take(){if(!active||capture==null)return;String name="VC_"+new SimpleDateFormat("yyyyMMdd_HHmmss_SSS",Locale.US).format(new Date())+".jpg";ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,name);values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(Build.VERSION.SDK_INT>=29)values.put(MediaStore.Images.Media.RELATIVE_PATH,"DCIM/VolumeCamera");ImageCapture.OutputFileOptions options=new ImageCapture.OutputFileOptions.Builder(getContentResolver(),MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values).build();capture.takePicture(options,io,new ImageCapture.OnImageSavedCallback(){public void onImageSaved(ImageCapture.OutputFileResults out){Uri uri=out.getSavedUri();if(uri!=null)mirror(uri,name);runOnUiThread(()->{status.setText("Saved "+name);handler.postDelayed(cycle,Settings.interval(CaptureActivity.this)*1000L);});}public void onError(ImageCaptureException e){runOnUiThread(()->{status.setText("Capture failed: "+e.getMessage());handler.postDelayed(cycle,Settings.interval(CaptureActivity.this)*1000L);});}});}
 private void mirror(Uri source,String name){Uri tree=Settings.drive(this);if(tree==null)return;try{DocumentFile folder=DocumentFile.fromTreeUri(this,tree);DocumentFile target=folder==null?null:folder.createFile("image/jpeg",name);if(target==null)return;try(InputStream in=getContentResolver().openInputStream(source);OutputStream out=getContentResolver().openOutputStream(target.getUri(),"w")){if(in!=null&&out!=null){byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);}}}catch(Exception ignored){runOnUiThread(()->Toast.makeText(this,"Cloud copy failed; camera-roll copy was kept",Toast.LENGTH_LONG).show());}}
 private void stopAndFinish(){active=false;handler.removeCallbacksAndMessages(null);getSystemService(NotificationManager.class).cancel(Notifications.CAPTURE_ID);finish();}
 @Override protected void onDestroy(){if(isFinishing())active=false;handler.removeCallbacksAndMessages(null);io.shutdown();getSystemService(NotificationManager.class).cancel(Notifications.CAPTURE_ID);super.onDestroy();}
}
